function findLengthOfLCIS(nums) {
  let left = 0;
  let best = 1;

  for (let right = 1; right < nums.length; right++) {
    if (nums[right] <= nums[right - 1]) {
      left = right;
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}

