function findLengthOfLCIS(nums) {
  let longest = 0;
  for (let start = 0; start < nums.length; start++) {
    let end = start;
    while (end + 1 < nums.length && nums[end] < nums[end + 1]) end += 1;
    longest = Math.max(longest, end - start + 1);
  }
  return longest;
}

