function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'small') {
    const n = int(1, 10);
    const span = rand() < 0.5 ? 3 : 20;
    const nums = Array.from({ length: n }, () => int(-span, span));
    if (rand() < 0.25) nums.sort((a, b) => a - b);
    return [nums];
  }
  // Large inputs are made of increasing runs of random lengths so that long windows appear.
  const n = int(1500, 2000);
  const limit = 1e9;
  const nums = [];
  let value;
  while (nums.length < n) {
    const run = int(1, rand() < 0.1 ? 400 : 30);
    value = int(-limit, limit - 2000);
    for (let i = 0; i < run && nums.length < n; i++) {
      nums.push(value);
      value += int(rand() < 0.2 ? 0 : 1, 3);
    }
  }
  return [nums];
}
